# MISE depends=["setup:external:check"]
# MISE tools={uv="latest", python="3.14"}

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Local services are for development only.
if os.environ.get("MISE_ENV", "") != "dev":
  sys.exit(0)

helpers.print_header("Stopping the local services ...")
result = helpers.tool(
  "docker",
  "compose",
  "--file",
  f"{os.environ['MISE_PROJECT_ROOT']}/.tools/docker-compose.yaml",
  "down",
  "--remove-orphans",
  "--volumes",
)
sys.exit(result.returncode)
